// Cách 1: chạy trong MockMvc, controller chạy trên cùng thread nên rollback được
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class OrderApiTest {
    @Autowired MockMvc mvc;
    @Autowired OrderRepository orders;

    @Test
    void createOrder() throws Exception {
        mvc.perform(post("/orders").param("sku", "PHO-01")).andExpect(status().isOk());
        assertEquals(1, orders.count());
    }

    @Test
    void listIsEmptyAtStart() {
        assertEquals(0, orders.count());
    }
}

